from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


def items(value: str) -> list[str]:
    return [item.strip() for item in value.split("；") if item.strip()]


def tests(value: str) -> list[dict[str, object]]:
    result = []
    for item in items(value):
        name, finding = item.split("=", 1)
        result.append(
            {
                "test_name": name,
                "result": finding,
                "trigger_keywords": [name, name.replace("检查", ""), "申请" + name],
            }
        )
    return result


def seed(
    case_id: str,
    title: str,
    title_en: str,
    department: str,
    specialty: str,
    difficulty: str,
    chief_complaint: str,
    patient: tuple[int, str, str],
    communication_style: str,
    opening_statement: str,
    present_illness: str,
    past_history: str,
    physical_exam: str,
    available_tests: str,
    diagnosis: str,
    differentials: str,
    scoring_points: str,
    risks: str,
    guidelines: str,
    followups: str,
    symptoms: str,
    training_goal: str,
) -> dict[str, object]:
    age, gender, occupation = patient
    test_rows = tests(available_tests)
    risk_rows = items(risks)
    scoring_rows = items(scoring_points)
    differential_rows = items(differentials)
    graph_ids = [
        f"case:{case_id}",
        f"diagnosis:{case_id}",
        *[f"symptom:{value}" for value in items(symptoms)],
        *[f"test:{row['test_name']}" for row in test_rows[:2]],
    ]
    variants = [
        {
            "variant_id": "A",
            "label": "病例变体 A",
            "age": age,
            "gender": gender,
            "communication_style": communication_style,
            "opening_statement": opening_statement,
            "distractor": "无额外干扰信息",
        },
        {
            "variant_id": "B",
            "label": "病例变体 B",
            "age": max(6, age + 7),
            "gender": gender,
            "communication_style": f"先简短回答，追问后再补充；{communication_style}",
            "opening_statement": opening_statement.replace("医生，", "医生您好，"),
            "distractor": "近期睡眠欠佳，但与核心诊断逻辑无直接关系",
        },
        {
            "variant_id": "C",
            "label": "病例变体 C",
            "age": max(6, age - 5),
            "gender": gender,
            "communication_style": f"表达略显紧张；{communication_style}",
            "opening_statement": f"我有点担心，{opening_statement}",
            "distractor": "近期工作或学习压力增加",
        },
    ]
    high_risk_omissions = [
        {
            "id": f"{case_id}_risk_{index + 1}",
            "level": "danger" if index == 0 else "warning",
            "text": value,
            "suggestion": f"请围绕“{value.replace('未', '', 1)}”补充问诊、检查或处置。",
            "keywords": [part for part in value.replace("未", "").replace("及时", "").split("和") if part],
        }
        for index, value in enumerate(risk_rows)
    ]
    history = {
        "present_illness": items(present_illness),
        "past_history": items(past_history),
        "medication_history": ["既往用药需结合当前病例继续追问", "否认自行使用来源不明药物"],
        "allergy_history": ["否认明确药物及食物过敏史"],
        "personal_history": [f"职业：{occupation}", "近期生活节律需进一步询问"],
        "family_history": ["家族中未发现完全相同症状，相关慢性病史需继续核实"],
    }
    patient_profile = {
        "age": age,
        "gender": gender,
        "occupation": occupation,
        "personality": "配合教学问诊，但不会主动补充未被问及的信息",
        "communication_style": communication_style,
    }
    exam_map = {str(row["test_name"]): str(row["result"]) for row in test_rows}
    return {
        "case_id": case_id,
        "id": case_id,
        "title_zh": title,
        "title_en": title_en,
        "title": title,
        "department": department,
        "specialty": specialty,
        "difficulty": difficulty,
        "scenario": f"{department}虚拟教学门诊：围绕{chief_complaint}完成问诊、鉴别、检查与安全决策。",
        "chief_complaint": chief_complaint,
        "symptom_tags": items(symptoms),
        "training_goals": [training_goal, "结构化问诊", "鉴别诊断", "检查选择", "风险识别"],
        "learning_goals": [training_goal, "鉴别诊断", "安全决策"],
        "recommended_minutes": 20 if difficulty != "高阶" else 25,
        "completion_status": "未训练",
        "patient_profile": patient_profile,
        "patient_profile_text": f"{age}岁{gender}，{occupation}，虚拟教学病例",
        "speaking_style": communication_style,
        "opening_statement": opening_statement,
        "opening": opening_statement,
        "history": history,
        "present_illness": "；".join(history["present_illness"]),
        "past_history": "；".join(history["past_history"]),
        "personal_history": "；".join(history["personal_history"]),
        "family_history": "；".join(history["family_history"]),
        "physical_exam": items(physical_exam),
        "physical_exam_text": "；".join(items(physical_exam)),
        "available_tests": test_rows,
        "available_exams": [str(row["test_name"]) for row in test_rows],
        "exam_results": exam_map,
        "hidden_final_diagnosis": diagnosis,
        "differential_diagnoses": differential_rows,
        "key_scoring_points": scoring_rows,
        "high_risk_misses": risk_rows,
        "high_risk_omissions": high_risk_omissions,
        "common_student_errors": [
            f"只围绕“{chief_complaint}”重复追问，未形成问题表征",
            f"过早锚定为{diagnosis}，忽略危险鉴别",
        ],
        "recommended_guidelines": items(guidelines),
        "related_knowledge_ids": [f"knowledge:{case_id}", *[f"knowledge:{x}" for x in items(symptoms)]],
        "related_graph_node_ids": graph_ids,
        "graph_node_ids": graph_ids,
        "recommended_followups": items(followups),
        "recommended_retraining": items(followups),
        "patient_answer_rules": {
            "can_only_answer_known_facts": True,
            "do_not_reveal_final_diagnosis": True,
            "unknown_answer": "这个我不太清楚，医生您能再具体问一下吗？",
        },
        "case_variants": variants,
        "source": {
            "type": "synthetic",
            "name": "临思智训虚拟教学病例库",
            "license_review_required": False,
            "contains_real_patient_data": False,
        },
        "script": {
            "identity": f"{age}岁{gender}，{occupation}",
            "style": communication_style,
            "opening": opening_statement,
            "answers": [
                {"keywords": ["主诉", "哪里不舒服", "怎么了"], "reply": f"我主要是{chief_complaint}。"},
                {"keywords": ["现病史", "多久", "开始", "诱因", "经过"], "reply": "；".join(history["present_illness"])},
                {"keywords": ["既往史", "以前", "基础病"], "reply": "；".join(history["past_history"])},
                {"keywords": ["用药", "吃药", "药物"], "reply": "；".join(history["medication_history"])},
                {"keywords": ["过敏", "药物过敏"], "reply": "；".join(history["allergy_history"])},
                {"keywords": ["个人史", "吸烟", "饮酒", "职业"], "reply": "；".join(history["personal_history"])},
                {"keywords": ["家族史", "遗传"], "reply": "；".join(history["family_history"])},
                {"keywords": ["查体", "体格检查", "生命体征"], "reply": "这些需要医生完成相应查体后获取。"},
            ],
        },
    }


