def validate(cases: list[dict[str, object]]) -> None:
    ids_seen: set[str] = set()
    for case in cases:
        case_id = str(case["case_id"])
        assert case_id not in ids_seen, f"duplicate case_id: {case_id}"
        ids_seen.add(case_id)
        assert len(case["differential_diagnoses"]) >= 3, case_id
        assert len(case["key_scoring_points"]) >= 5, case_id
        assert case["high_risk_misses"], case_id
        assert case["source"]["type"] == "synthetic", case_id
        assert case["patient_answer_rules"]["do_not_reveal_final_diagnosis"] is True, case_id


def main() -> None:
    validate(CASES)
    payload = json.dumps(CASES, ensure_ascii=False, indent=2)
    (ROOT / "data" / "cases.json").write_text(payload + "\n", encoding="utf-8")
    (ROOT / "frontend" / "src" / "data" / "cases.ts").write_text(
        "import type { CaseSummary } from '../types';\n\n"
        f"export const mockCases: CaseSummary[] = {payload};\n",
        encoding="utf-8",
    )
    (ROOT / "backend" / "app" / "data" / "cases.py").write_text(
        "from __future__ import annotations\n\n"
        "# Generated by scripts/generate_case_library.py. Do not edit by hand.\n"
        f"CASES = {repr(CASES)}\n",
        encoding="utf-8",
    )
    print(f"generated {len(CASES)} synthetic teaching cases")


if __name__ == "__main__":
    main()
